{
  "status": "STABLE",
  "core_findings": [
    "Training positives generally outrank sampled negatives across all four datasets. Movies_and_TV has the weakest separation (5.05% wrong ranks; margin p10 1.1204), while CDs_and_Vinyl has no observed wrong ranks or margins below 0.5.",
    "Recent-history deletion reduces mean margins in every dataset, but shuffle effects are nearly zero for short prefixes. These probes show history sensitivity, with deletion effects confounded by repacking and position changes."
  ],
  "key_implications": [
    "The model separates observed training pairs effectively, with the most residual confusion in Movies_and_TV.",
    "Electronics has the greatest measured embedding alignment, which does not establish representation collapse or recommendation diversity.",
    "Strong training margins do not establish validation HR@10 or generalization."
  ],
  "evidence": {
    "headline_metrics": {
      "Movies_and_TV:pos_neg_neg_beats_pos_rate": 0.0505,
      "Movies_and_TV:pos_neg_margin_p10": 1.1204,
      "CDs_and_Vinyl:pos_neg_margin_mean": 17.3274,
      "CDs_and_Vinyl:pos_neg_small_margin_rate": 0.0,
      "Electronics:embedding_collapse_score": 0.6418
    },
    "brief_metric_read": {
      "pos_neg_margin_p10": "Positive in all datasets; even the lower margin tail generally favors positives.",
      "training_history_dependence": "Recent deletion lowers mean margins by 0.703–2.428; these are paired training diagnostics.",
      "embedding_collapse_score": "Highest in Electronics; measures directional alignment, not recommendation diversity."
    }
  }
}
